import {CONFIG,SKILLS,JOBS,ITEMS,HOUSING,DAILY_QUESTS,ACHIEVEMENTS,xpNeeded} from '../data/config.js';
import {freshProfile} from '../systems/profile.js';
export const dayKey=now=>Math.floor(now/86400000);
export const clamp=(n,min=0,max=CONFIG.maxMoney)=>Number.isFinite(n)?Math.min(max,Math.max(min,n)):min;
export const round=n=>Math.round((n+Number.EPSILON)*100)/100;
export function freshState(now=Date.now()) {return {saveVersion:CONFIG.saveVersion,profile:freshProfile(),money:CONFIG.startMoney,gems:CONFIG.startGems,xp:0,level:1,bank:0,bankXP:0,job:'helper',jobs:['helper'],items:['oldPhone','basicClothes'],equipped:{phone:'oldPhone',clothes:'basicClothes'},skills:Object.fromEntries(SKILLS.map(k=>[k,0])),housing:0,training:null,stats:{earned:0,work:0,collected:0,bought:0,training:0},daily:{day:dayKey(now),work:0,collect:0,training:0,claimed:[],gift:false,adGift:false,incomeAds:0},achievements:[],settings:{language:'ru',sound:true,music:false,vibration:true,notifications:false,motion:true,effects:true},lastTick:now,lastWork:0,lastEvent:0,playtime:0,tutorial:0,event:null,eventSeen:[],followers:0,businesses:[],offline:null,offlineReward:null,boosts:[],commerce:{starterOwned:false,receipts:[],rewardReceipts:[],cosmetics:[],decorations:[]}};}
export function baseIncome(s) {const job=JOBS.find(j=>j.id===s.job)||JOBS[0];const itemBonus=Object.values(s.equipped).reduce((sum,id)=>sum+(ITEMS.find(i=>i.id===id)?.bonus||0),0);const skills=s.skills.discipline*CONFIG.disciplineIncomeBonus+(job.branch==='tech'?s.skills.technology:job.branch==='creative'?s.skills.creativity:s.skills.charisma)*CONFIG.branchIncomeBonus;return round(job.incomePerSecond*(1+itemBonus+HOUSING[s.housing].bonus+skills));}
export function boostFactor(s,at=s.lastTick){return Math.max(1,...(s.boosts||[]).filter(b=>b.startsAt<=at&&b.endsAt>at).map(b=>b.factor));}
export function income(s,at=s.lastTick){return round(baseIncome(s)*boostFactor(s,at));}
export function registerOffline(s,result){if(result.seconds<60||result.money<=0)return;s.offlineReward={id:`offline:${s.lastTick}`,amount:round((s.offlineReward?.amount||0)+result.money),seconds:Math.min(CONFIG.offlineHours*3600,(s.offlineReward?.seconds||0)+result.seconds)};s.offline={seconds:s.offlineReward.seconds,money:s.offlineReward.amount};}
export function addMoney(s,amount) {const n=round(clamp(amount));s.money=round(clamp(s.money+n));s.stats.earned=round(clamp(s.stats.earned+n));return n;}
export function spend(s,cost) {if(!Number.isFinite(cost)||cost<0||s.money<cost)return false;s.money=round(s.money-cost);return true;}
export function addXP(s,amount) {s.xp+=clamp(amount,0,1e7);let levels=0;while(s.level<CONFIG.maxLevel&&s.xp>=xpNeeded(s.level)){s.xp-=xpNeeded(s.level);s.level++;s.gems+=CONFIG.levelGems;levels++;}if(s.level===CONFIG.maxLevel)s.xp=0;return levels;}
export function refreshDaily(s,now) {const day=dayKey(now);if(day>s.daily.day)s.daily={day,work:0,collect:0,training:0,claimed:[],gift:false,adGift:false,incomeAds:0};}
export function advance(s,now=Date.now(),offline=false) {
 if(!Number.isFinite(now)||now<s.lastTick)return {seconds:0,money:0};refreshDaily(s,now);
 const seconds=Math.min((now-s.lastTick)/1000,CONFIG.offlineHours*3600),start=s.lastTick,end=start+seconds*1000,previousBank=s.bank;
 const points=[start,end,...(s.boosts||[]).flatMap(b=>[b.startsAt,b.endsAt]).filter(t=>t>start&&t<end)].sort((a,b)=>a-b);
 let earned=0;for(let i=1;i<points.length;i++)earned+=income(s,points[i-1])*(points[i]-points[i-1])/1000;
 const capacity=Math.max(s.bank,baseIncome(s)*CONFIG.offlineHours*3600*Math.max(1,...points.map(t=>boostFactor(s,t))));s.bank=round(Math.min(capacity,s.bank+earned));
 s.bankXP=Math.min(CONFIG.offlineMaxXP,s.bankXP+seconds*CONFIG.passiveXPPerSecond);s.lastTick=now;if(!offline)s.playtime+=seconds;
 s.boosts=(s.boosts||[]).filter(b=>b.endsAt>now);
 if(s.training&&now>=s.training.endsAt){s.skills[s.training.skill]=Math.min(CONFIG.maxSkill,s.skills[s.training.skill]+1);s.stats.training++;s.daily.training++;addXP(s,CONFIG.trainingXP);s.training=null;}
 return {seconds,money:round(s.bank-previousBank)};
}
export function collect(s) {if(s.bank<1)return {ok:false,reason:'empty'};const amount=addMoney(s,s.bank);s.bank=0;s.offlineReward=null;s.offline=null;const levels=addXP(s,s.bankXP);s.bankXP=0;s.stats.collected++;s.daily.collect++;s.tutorial=Math.max(s.tutorial,1);return {ok:true,amount,levels};}
export function work(s,now=Date.now()) {if(!s.tutorial)return {ok:false,reason:'firstCollect'};if(now-s.lastWork<CONFIG.workCooldownMs)return {ok:false,reason:'cooldown'};s.lastWork=now;s.stats.work++;s.daily.work++;const amount=addMoney(s,income(s)*CONFIG.workSeconds);const levels=addXP(s,CONFIG.workXP);s.tutorial=Math.max(s.tutorial,2);return {ok:true,amount,levels};}
export function hasItem(s,id){if(s.items.includes(id))return true;const required=ITEMS.find(i=>i.id===id);return !!required&&s.items.some(owned=>{const i=ITEMS.find(x=>x.id===owned);return i?.slot===required.slot&&i.price>=required.price;});}
export function jobRequirements(s,j) {const missing=[];if(s.level<j.levelRequirement)missing.push({kind:'level',value:j.levelRequirement});for(const [id,n] of Object.entries(j.skillRequirements))if(s.skills[id]<n)missing.push({kind:'skill',id,value:n});for(const id of j.itemRequirements)if(!hasItem(s,id))missing.push({kind:'item',id});if(j.previousJob&&!s.jobs.includes(j.previousJob))missing.push({kind:'job',id:j.previousJob});return missing;}
export function takeJob(s,id) {const j=JOBS.find(x=>x.id===id);if(!j)return {ok:false,reason:'invalid'};if(s.job===id)return {ok:false,reason:'current'};if(!s.jobs.includes(id)){if(jobRequirements(s,j).length)return {ok:false,reason:'requirements'};if(!spend(s,j.unlockCost))return {ok:false,reason:'money'};s.jobs.push(id);addXP(s,CONFIG.careerXP);}s.job=id;return {ok:true};}
export function buyItem(s,id){const i=ITEMS.find(x=>x.id===id);if(!i)return {ok:false,reason:'invalid'};if(s.items.includes(id)){s.equipped[i.slot]=id;return {ok:true,equipped:true};}if(s.level<i.levelRequirement||s.level<2)return {ok:false,reason:'level'};if(!spend(s,i.price))return {ok:false,reason:'money'};s.items.push(id);s.equipped[i.slot]=id;s.stats.bought++;addXP(s,CONFIG.purchaseXP);s.tutorial=Math.max(s.tutorial,3);return {ok:true};}
export function buyHousing(s,id){const h=HOUSING.find(x=>x.id===id);if(!h||id!==s.housing+1)return {ok:false,reason:'invalid'};if(s.level<h.levelRequirement)return {ok:false,reason:'level'};if(!spend(s,h.price))return {ok:false,reason:'money'};s.housing=id;addXP(s,CONFIG.housingXP);return {ok:true};}
export const trainingCost=(s,skill)=>Math.round(CONFIG.trainingBaseCost*Math.pow(CONFIG.trainingGrowth,s.skills[skill]||0));
export const trainingDuration=s=>Math.max(5,CONFIG.trainingBaseSeconds/(1+s.skills.discipline*.04));
export function train(s,skill,now=Date.now()){if(!SKILLS.includes(skill))return {ok:false,reason:'invalid'};if(s.level<3)return {ok:false,reason:'level'};if(s.training)return {ok:false,reason:'training'};if(s.skills[skill]>=CONFIG.maxSkill)return {ok:false,reason:'max'};if(!spend(s,trainingCost(s,skill)))return {ok:false,reason:'money'};s.training={skill,startsAt:now,endsAt:now+trainingDuration(s)*1000};return {ok:true};}
export function statValue(s,id){return id==='jobs'?s.jobs.length:id==='housing'?s.housing:id==='level'?s.level:s.stats[id]||0;}
export function claimAchievement(s,id){const a=ACHIEVEMENTS.find(x=>x.id===id);if(!a||s.achievements.includes(id)||statValue(s,a.stat)<a.target)return {ok:false,reason:'requirements'};s.achievements.push(id);s.gems+=a.gems;addXP(s,a.xp);return {ok:true};}
export function claimQuest(s,id){const q=DAILY_QUESTS.find(x=>x.id===id);if(!q||s.daily.claimed.includes(id)||s.daily[id]<q.target)return {ok:false,reason:'requirements'};s.daily.claimed.push(id);addMoney(s,q.money);addXP(s,q.xp);s.gems++;return {ok:true};}
export function claimGift(s){if(s.daily.gift)return {ok:false,reason:'claimed'};s.daily.gift=true;s.gems+=CONFIG.dailyGems;addMoney(s,CONFIG.dailyMoney);return {ok:true};}
